    '.invite-name','.invite-code','.invite-detail-head h2','.invite-detail-head p','.invite-detail-grid dd','.invite-product-options strong','.invite-product-options small','.invite-asset-options strong','.invite-tags',
    '.invite-email-letter','.invite-email-meta dd','.invite-email-guidance','.audit-row','.library-dialog .stack > p > strong',
