  const dataTableUI = '.btn,.badge,.row-actions,.team-current-member,[data-invite-access-policy],[data-label="员工身份"],[data-label="Employee role"],[data-label="演示角色"],[data-label="Demo role"],[data-label="负责邀请"],[data-label="Owned invitations"],[data-label="访问权限"],[data-label="Access"]';
