  function isProtected(element, attribute = false) {
    if (!element || element.closest(skip)) return true;
    if (!attribute && element.closest('input,textarea,select option:not([value])')) return true;
    if (element.closest('select[name="owner"] option')) return false;
    if (element.closest('.invite-quote-invalid-note')) return false;
    if (element.closest(sourceContent)) return true;
    if (element.id === 'page-banner-title' && /^#\/(assets|downloads)\?/.test(location.hash)) {
      const product = new URLSearchParams(location.hash.split('?')[1]).get('product');
      if (product && product !== 'unlinked') return true;
    }
    // Custom template names and descriptions belong to the uploaded document.
    const card = element.closest('.ex-template-card');
    if (card && !card.querySelector('[data-export]') && element.closest('.ex-template-copy h3,.ex-template-copy > p')) return true;
    const emailPlaceholder=element.closest('.team-member-table .invite-cell-note');
    if(emailPlaceholder&&['未填写邮箱',dictionary.get('未填写邮箱')].includes(emailPlaceholder.textContent.trim()))return false;
    if (element.closest('tbody') && !element.closest(dataTableUI)) return true;
    return false;
  }

  function translate(source, element, attribute = false) {
    const raw = source.trim();
    if (!raw) return source;
    // Names are user data. Translate only the role or record suffix on account labels.
    if (!attribute && element.closest('.profile-button > span:not(.avatar),select[name="owner"] option')) {
      const member=raw.match(/^(.+) · (管理员|业务人员|客户)$/),record=raw.match(/^(.+)（当前记录）$/);
      if(member)return source.replace(raw,`${member[1]} · ${dictionary.get(member[2])}`);
      if(record)return source.replace(raw,`${record[1]} (current record)`);
      if(element.closest('select[name="owner"] option'))return source;
    }
    let result = dictionary.get(raw);
    if (result === undefined && attribute) {
      let match;
      if (element.matches?.('[data-quote-price],[data-quote-quantity]') && (match = raw.match(/^(.+) 报价(单价|数量)$/))) result = `${match[1]} quotation ${match[2] === '单价' ? 'unit price' : 'quantity'}`;
      else if ((match = raw.match(/^(选择|查看|预览|删除|上移|下移) (.+)$/))) result = `${{'选择':'Select','查看':'View','预览':'Preview','删除':'Delete','上移':'Move up','下移':'Move down'}[match[1]]} ${match[2]}`;
      else if ((match = raw.match(/^当前身份：(管理员|业务人员|客户)，切换身份$/))) result = `Current role: ${dictionary.get(match[1])}. Change role`;
      else if ((match = raw.match(/^当前账号：(.+)，(管理员|业务人员|客户)，返回登录$/))) result = `Current account: ${match[1]}, ${dictionary.get(match[2])}. Return to sign in`;
      else if ((match = raw.match(/^切换公司主体，当前 (UNIQMAG|UNICO)$/))) result = `Switch company, current: ${match[1]}`;
      else if (element.closest('[data-brand-filter]') && (match = raw.match(/^(.+)，(\d+) 个产品型号$/))) result = `${dictionary.get(match[1]) || match[1]}, ${match[2]} models`;
      else if ((match = raw.match(/^(查看图片|移除版本图片|分类名称) (\d+)$/))) result = `${{'查看图片':'View image','移除版本图片':'Remove variant image','分类名称':'Category name'}[match[1]]} ${match[2]}`;
    }
    if (result === undefined && !attribute) {
      let match;
      if (element.id === 'invite-quote-total-note') {
        if ((match = raw.match(/^(\d+) 项明细 · (\d+) 项待填写单价或数量$/))) result = `${match[1]} items · ${match[2]} need a unit price or quantity`;
        else if ((match = raw.match(/^(\d+) 项明细 · 单价 × 数量自动合计$/))) result = `${match[1]} items · Total = unit price × quantity`;
      }
      if (element.closest('.customer-quote-total small') && (match = raw.match(/^(\d+) 个明细$/))) result = `${match[1]} items`;
      if (element.closest('.invite-detail-quotation > span') && (match = raw.match(/^(.+) · (\d+) 项明细$/))) result = `${match[1]} · ${match[2]} items`;
      if (element.closest('.invite-detail-quotation > small') && (match = raw.match(/^报价有效期：(\d{4}-\d{2}-\d{2})，与访问截止时间以较早者为准。$/))) result = `Quotation valid until ${match[1]}, or the access deadline if earlier.`;
      if (element.closest('[data-invite-access-policy]')) result = raw.split(' · ').map(part => dictionary.get(part) || part).join(' · ');
      if (element.closest('.collection-access-note .badge')) result = raw.split(' · ').map(part => dictionary.get(part) || part).join(' · ');
      if (element.id === 'invite-selection-summary' && (match = raw.match(/^已选 (\d+) 个产品 · (\d+) 份已发布素材 · 当前筛选 (\d+) 个产品$/))) result = `${match[1]} products selected · ${match[2]} published assets · ${match[3]} matching products`;
      const countContext = element.closest('#portal-count,#cat-folder-summary,#cat-selected-count,#cat-detail-count,.collection-results,.selection-tray,.cat-folder-count,.cat-list-summary,.cat-variant-footer,.invite-result-count,.invite-grant-heading,.invite-detail-grants,.team-list-heading,.ex-selection-tags,.ex-select-count,.ex-download-summary,.ex-toolbar,.ex-export-options,.toolbar,.cat-dialog-actions,[data-label="访问权限"],[data-label="Access"],[data-label="负责邀请"],[data-label="Owned invitations"]');
      if (countContext) {
        if ((match = raw.match(/^(\d+) 个产品型号( · .+)?$/))) result = `${match[1]} models${match[2] || ''}`;
        else if ((match = raw.match(/^已选 (\d+) 个型号 · (\d+) 个 SKU$/))) result = `${match[1]} models · ${match[2]} SKUs selected`;
        else if ((match = raw.match(/^已选 (\d+) 份素材$/))) result = `${match[1]} assets selected`;
        else if ((match = raw.match(/^找到 (\d+) 个资料夹$/))) result = `${match[1]} folders found`;
        else if ((match = raw.match(/^(\d+) 个产品(?: · (\d+) 份素材待关联)?$/))) result = `${match[1]} products${match[2] ? ` · ${match[2]} unlinked assets` : ''}`;
        else if ((match = raw.match(/^(\d+) (个产品系列|个配色|张图片|张详情图|份可浏览素材|份素材|份已归档|个结果|条记录|条)$/))) result = `${match[1]} ${{'个产品系列':'product series','个配色':'colors','张图片':'images','张详情图':'detail images','份可浏览素材':'viewable assets','份素材':'assets','份已归档':'archived','个结果':'results','条记录':'records','条':'invitations'}[match[2]]}`;
        else if ((match = raw.match(/^(\d+) 份已发布素材可授权浏览$/))) result = `${match[1]} published assets available to authorize`;
        else if ((match = raw.match(/^(\d+) 份素材可浏览$/))) result = `${match[1]} viewable assets`;
        else if ((match = raw.match(/^(\d+) 张图片 \/ (\d+) 行资料$/))) result = `${match[1]} images / ${match[2]} rows`;
        else if ((match = raw.match(/^(\d+) 份已完成 · 保存在当前浏览器$/))) result = `${match[1]} completed · Saved in this browser`;
        else if ((match = raw.match(/^(\d+) 位启用 · (\d+) 位总计$/))) result = `${match[1]} active · ${match[2]} total`;
        else if (raw === '已选') result = 'Selected';
        else if (raw === '个配色') result = 'colors';
      }
      if (result === undefined && element.closest('.banner-dashboard-note') && raw.startsWith('本机数据 · 默认：')) result = 'Local data · Default: ' + raw.slice('本机数据 · 默认：'.length);
      if (result === undefined && element.closest('.ex-choice .badge') && (match = raw.match(/^固定模板 · (.+)$/))) result = `Built-in · ${match[1]}`;
      if (result === undefined && element.closest('.cat-folder-usage,.cat-asset-info > p')) {
        const pieces = raw.split(' · ');
        if (pieces.every(piece => dictionary.has(piece) || /^(通用|中文|英文|日文|v\d+)$/.test(piece))) result = pieces.map(piece => dictionary.get(piece) || ({'通用':'All languages','中文':'Chinese','英文':'English','日文':'Japanese'}[piece]) || piece).join(' · ');
      }
    }
    return result === undefined ? source : source.replace(raw, result);
  }

  function updateText(node) {
    const element = node.parentElement;
    if (isProtected(element)) return;
    const current = node.nodeValue;
    let record = originalText.get(node);
    // Renderers may reuse a text node. A new source string becomes its own baseline.
    if (!record || current !== record.rendered) record = {source:current,rendered:current};
    const next = english() ? translate(record.source, element) : record.source;
    record.rendered = next;
    originalText.set(node, record);
    if (current !== next) node.nodeValue = next;
  }

  function updateAttributes(element) {
    if (element.closest(skip)) return;
    const protectedElement = isProtected(element, true);
    // Mobile table captions are interface metadata, even when the cell holds user data.
    if (protectedElement && !element.hasAttribute('data-label')) return;
    let records = originalAttributes.get(element);
    if (!records) {records = {}; originalAttributes.set(element, records);}
    attributes.forEach(name => {
      if (protectedElement && name !== 'data-label') return;
      if (!element.hasAttribute(name)) {delete records[name]; return;}
      const current = element.getAttribute(name);
      let record = records[name];
      if (!record || current !== record.rendered) record = {source:current,rendered:current};
      const next = english() ? translate(record.source, element, true) : record.source;
      record.rendered = next; records[name] = record;
      if (current !== next) element.setAttribute(name, next);
    });
  }

  function walk(root) {
    if (root.nodeType === Node.TEXT_NODE) {updateText(root); return;}
    if (root.nodeType !== Node.ELEMENT_NODE || root.closest(skip)) return;
    updateAttributes(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      if (node.nodeType === Node.TEXT_NODE) updateText(node);
      else updateAttributes(node);
    }
  }

  let titleRecord;
  function updateTitle() {
    const current = document.title;
    if (!titleRecord || current !== titleRecord.rendered) titleRecord = {source:current,rendered:current};
    const source = titleRecord.source;
    const match = source.match(/^(.+) · (UNIQMAG|UNICO)$/);
    const next = english() && match ? `${dictionary.get(match[1]) || match[1]} · ${match[2]}` : source;
    titleRecord.rendered = next;
    if (current !== next) document.title = next;
  }

  function observe() {
    if (document.body) observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attributes});
    const title = document.querySelector('title');
    if (title) observer.observe(title,{subtree:true,childList:true,characterData:true});
  }
  function refresh(roots) {
    if (refreshing) return;
    refreshing = true;
    observer?.disconnect();
    try {
      (roots || [document.body]).filter(Boolean).forEach(walk);
      updateTitle();
    } finally {refreshing = false; observe();}
  }
  observer = new MutationObserver(changes => {
    const roots = new Set();
    changes.forEach(change => {
      if (change.type === 'childList') change.addedNodes.forEach(node => roots.add(node));
      else roots.add(change.target);
    });
    refresh([...roots].filter(node => node.isConnected));
  });
  document.addEventListener('library:preferences-change',() => {
    const language = window.LibraryPreferences?.language;
    if (language === lastLanguage) return;
    lastLanguage = language;
    refresh();
  });
  window.LibraryLocale = Object.freeze({refresh:() => refresh()});
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded',() => refresh(),{once:true});
